SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @MatchInput TABLE (
    source_match_id INT NOT NULL PRIMARY KEY,
    week INT NOT NULL,
    home_club_name NVARCHAR(120) NOT NULL,
    away_club_name NVARCHAR(120) NOT NULL
);


DECLARE @MatchMap TABLE (
    source_match_id INT NOT NULL PRIMARY KEY,
    match_id INT NOT NULL UNIQUE
);

SELECT input.source_match_id, match_row.match_id
FROM @MatchInput AS input
INNER JOIN dbo.season AS season
    ON season.name = N'2025-2026'
INNER JOIN dbo.[match] AS match_row
    ON match_row.season_id = season.season_id
    AND match_row.week = input.week
INNER JOIN dbo.club AS home_club
    ON home_club.club_id = match_row.home_club_id
    AND home_club.name = input.home_club_name
INNER JOIN dbo.club AS away_club
    ON away_club.club_id = match_row.away_club_id
    AND away_club.name = input.away_club_name;

IF (SELECT COUNT(*) FROM @MatchMap) <> 306
    THROW 52001, 'Every TFF fixture must resolve to one database match.', 1;

DECLARE @SubstitutionInput TABLE (
    source_match_id INT NOT NULL,
    event_no INT NOT NULL,
    minute INT NOT NULL,
    incoming_player_name NVARCHAR(120) NOT NULL,
    incoming_role NVARCHAR(30) NOT NULL,
    outgoing_player_name NVARCHAR(120) NOT NULL,
    outgoing_role NVARCHAR(30) NOT NULL,
    is_injury BIT NOT NULL,
    PRIMARY KEY (source_match_id, event_no)
);





IF (SELECT COUNT(*) FROM @SubstitutionInput) <> 2702
    THROW 52021, 'Expected the sourced substitutions.', 1;

IF EXISTS (
    SELECT 1
    FROM @SubstitutionInput AS input
    CROSS APPLY (VALUES (input.incoming_player_name), (input.outgoing_player_name)) AS participant(player_name)
    LEFT JOIN dbo.person AS person
        ON person.name = participant.player_name
    LEFT JOIN dbo.player AS player
        ON player.person_id = person.person_id
    WHERE player.person_id IS NULL
)
    THROW 52022, 'Every substitution participant must resolve to a player profile.', 1;

IF EXISTS (SELECT 1 FROM dbo.substitution)
    THROW 52023, 'Substitutions are already loaded.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    SELECT match_map.match_id, input.event_no, input.minute
    FROM @SubstitutionInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id;

    SELECT match_map.match_id, input.event_no, player.person_id, input.incoming_role
    FROM @SubstitutionInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.incoming_player_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id
    UNION ALL
    SELECT match_map.match_id, input.event_no, player.person_id, input.outgoing_role
    FROM @SubstitutionInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.outgoing_player_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id;

    SELECT match_map.match_id, input.event_no, input.is_injury
    FROM @SubstitutionInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
